import 'package:geolocator/geolocator.dart';

class LocationService {
  /// 권한 확인 및 요청
  static Future<bool> handlePermission() async {
    bool serviceEnabled;
    LocationPermission permission;

    // 1. 위치 서비스 활성화 확인
    serviceEnabled = await Geolocator.isLocationServiceEnabled();
    if (!serviceEnabled) {
      // 위치 서비스가 비활성화됨
      return false;
    }

    // 2. 현재 권한 상태 확인
    permission = await Geolocator.checkPermission();

    if (permission == LocationPermission.denied) {
      // 권한이 거부된 상태 → 권한 요청
      permission = await Geolocator.requestPermission();
      if (permission == LocationPermission.denied) {
        // 사용자가 권한을 거부함
        return false;
      }
    }

    if (permission == LocationPermission.deniedForever) {
      // 영구적으로 거부됨 → 설정으로 이동 필요
      // Geolocator.openAppSettings(); 또는 Geolocator.openLocationSettings();
      return false;
    }

    // whileInUse 또는 always 권한 획득
    return true;
  }

  /// 현재 위치 가져오기
  static Future<Position?> getCurrentLocation() async {
    final hasPermission = await handlePermission();
    if (!hasPermission) {
      return null;
    }

    return await Geolocator.getCurrentPosition(
      desiredAccuracy: LocationAccuracy.high,
    );
  }

  /// 마지막으로 알려진 위치 (캐시, 빠름)
  static Future<Position?> getLastKnownLocation() async {
    return await Geolocator.getLastKnownPosition();
  }
}

import 'dart:async';
import 'package:flutter/material.dart';
import 'package:geolocator/geolocator.dart';
import 'location_service.dart';

class LocationTrackingPage extends StatefulWidget {
  const LocationTrackingPage({super.key});

  @override
  State<LocationTrackingPage> createState() => _LocationTrackingPageState();
}

class _LocationTrackingPageState extends State<LocationTrackingPage> {
  Position? _currentPosition;
  StreamSubscription<Position>? _positionSubscription;
  bool _isTracking = false;
  final List<Position> _positionHistory = [];

  @override
  void dispose() {
    _stopTracking();
    super.dispose();
  }

  /// 위치 추적 시작
  Future<void> _startTracking() async {
    final hasPermission = await LocationService.handlePermission();
    if (!hasPermission) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('위치 권한이 필요합니다')),
      );
      return;
    }

    setState(() {
      _isTracking = true;
      _positionHistory.clear();
    });

    // 위치 스트림 설정
    const locationSettings = LocationSettings(
      accuracy: LocationAccuracy.high,
      distanceFilter: 10,  // 10미터 이동 시에만 업데이트
    );

    _positionSubscription = Geolocator.getPositionStream(
      locationSettings: locationSettings,
    ).listen(
      (Position position) {
        setState(() {
          _currentPosition = position;
          _positionHistory.add(position);
        });
      },
      onError: (error) {
        debugPrint('위치 추적 에러: $error');
      },
    );
  }

  /// 위치 추적 중지
  void _stopTracking() {
    _positionSubscription?.cancel();
    _positionSubscription = null;
    setState(() {
      _isTracking = false;
    });
  }

  /// 이동 거리 계산
  double _calculateTotalDistance() {
    if (_positionHistory.length < 2) return 0;

    double totalDistance = 0;
    for (int i = 1; i < _positionHistory.length; i++) {
      totalDistance += Geolocator.distanceBetween(
        _positionHistory[i - 1].latitude,
        _positionHistory[i - 1].longitude,
        _positionHistory[i].latitude,
        _positionHistory[i].longitude,
      );
    }
    return totalDistance;
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('위치 추적')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            // 현재 위치 정보
            Card(
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      '현재 위치',
                      style: Theme.of(context).textTheme.titleMedium,
                    ),
                    const SizedBox(height: 8),
                    if (_currentPosition != null) ...[
                      Text('위도: ${_currentPosition!.latitude.toStringAsFixed(6)}'),
                      Text('경도: ${_currentPosition!.longitude.toStringAsFixed(6)}'),
                      Text('고도: ${_currentPosition!.altitude.toStringAsFixed(1)}m'),
                      Text('속도: ${(_currentPosition!.speed * 3.6).toStringAsFixed(1)} km/h'),
                      Text('정확도: ${_currentPosition!.accuracy.toStringAsFixed(1)}m'),
                    ] else
                      const Text('위치 정보 없음'),
                  ],
                ),
              ),
            ),

            const SizedBox(height: 16),

            // 추적 통계
            Card(
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      '추적 통계',
                      style: Theme.of(context).textTheme.titleMedium,
                    ),
                    const SizedBox(height: 8),
                    Text('기록 포인트: ${_positionHistory.length}개'),
                    Text('총 이동 거리: ${(_calculateTotalDistance() / 1000).toStringAsFixed(2)} km'),
                  ],
                ),
              ),
            ),

            const Spacer(),

            // 추적 시작/중지 버튼
            ElevatedButton.icon(
              onPressed: _isTracking ? _stopTracking : _startTracking,
              icon: Icon(_isTracking ? Icons.stop : Icons.play_arrow),
              label: Text(_isTracking ? '추적 중지' : '추적 시작'),
              style: ElevatedButton.styleFrom(
                backgroundColor: _isTracking ? Colors.red : Colors.green,
                foregroundColor: Colors.white,
                padding: const EdgeInsets.symmetric(vertical: 16),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:geolocator/geolocator.dart';

class DistanceCalculatorPage extends StatefulWidget {
  const DistanceCalculatorPage({super.key});

  @override
  State<DistanceCalculatorPage> createState() => _DistanceCalculatorPageState();
}

class _DistanceCalculatorPageState extends State<DistanceCalculatorPage> {
  // 예시 좌표들
  final Map<String, Map<String, double>> _landmarks = {
    '서울역': {'lat': 37.5547, 'lng': 126.9707},
    '강남역': {'lat': 37.4979, 'lng': 127.0276},
    '인천공항': {'lat': 37.4602, 'lng': 126.4407},
    '부산역': {'lat': 35.1152, 'lng': 129.0403},
  };

  String _selectedFrom = '서울역';
  String _selectedTo = '강남역';
  double? _distance;
  double? _bearing;

  void _calculateDistance() {
    final from = _landmarks[_selectedFrom]!;
    final to = _landmarks[_selectedTo]!;

    // 두 지점 간 거리 (미터)
    final distanceInMeters = Geolocator.distanceBetween(
      from['lat']!,
      from['lng']!,
      to['lat']!,
      to['lng']!,
    );

    // 두 지점 간 방위각 (0~360도, 북쪽 기준 시계방향)
    final bearing = Geolocator.bearingBetween(
      from['lat']!,
      from['lng']!,
      to['lat']!,
      to['lng']!,
    );

    setState(() {
      _distance = distanceInMeters;
      _bearing = bearing;
    });
  }

  String _getDirectionName(double bearing) {
    if (bearing >= 337.5 || bearing < 22.5) return '북';
    if (bearing >= 22.5 && bearing < 67.5) return '북동';
    if (bearing >= 67.5 && bearing < 112.5) return '동';
    if (bearing >= 112.5 && bearing < 157.5) return '남동';
    if (bearing >= 157.5 && bearing < 202.5) return '남';
    if (bearing >= 202.5 && bearing < 247.5) return '남서';
    if (bearing >= 247.5 && bearing < 292.5) return '서';
    return '북서';
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('거리 계산')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            // 출발지 선택
            Card(
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Text('출발지', style: TextStyle(fontWeight: FontWeight.bold)),
                    DropdownButton<String>(
                      value: _selectedFrom,
                      isExpanded: true,
                      items: _landmarks.keys.map((name) {
                        return DropdownMenuItem(value: name, child: Text(name));
                      }).toList(),
                      onChanged: (value) {
                        setState(() {
                          _selectedFrom = value!;
                          _distance = null;
                        });
                      },
                    ),
                  ],
                ),
              ),
            ),

            // 화살표 아이콘
            const Padding(
              padding: EdgeInsets.symmetric(vertical: 8),
              child: Icon(Icons.arrow_downward, size: 32),
            ),

            // 도착지 선택
            Card(
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Text('도착지', style: TextStyle(fontWeight: FontWeight.bold)),
                    DropdownButton<String>(
                      value: _selectedTo,
                      isExpanded: true,
                      items: _landmarks.keys.map((name) {
                        return DropdownMenuItem(value: name, child: Text(name));
                      }).toList(),
                      onChanged: (value) {
                        setState(() {
                          _selectedTo = value!;
                          _distance = null;
                        });
                      },
                    ),
                  ],
                ),
              ),
            ),

            const SizedBox(height: 16),

            // 거리 계산 버튼
            ElevatedButton(
              onPressed: _calculateDistance,
              child: const Text('거리 계산'),
            ),

            const SizedBox(height: 16),

            // 결과 표시
            if (_distance != null)
              Card(
                color: Colors.blue.shade50,
                child: Padding(
                  padding: const EdgeInsets.all(16),
                  child: Column(
                    children: [
                      Text(
                        '${(_distance! / 1000).toStringAsFixed(2)} km',
                        style: const TextStyle(
                          fontSize: 32,
                          fontWeight: FontWeight.bold,
                          color: Colors.blue,
                        ),
                      ),
                      const SizedBox(height: 8),
                      Text(
                        '방향: ${_getDirectionName(_bearing!)} (${_bearing!.toStringAsFixed(1)}°)',
                        style: const TextStyle(fontSize: 16),
                      ),
                    ],
                  ),
                ),
              ),
          ],
        ),
      ),
    );
  }
}

import 'dart:async';
import 'dart:io';
import 'package:flutter/material.dart';
import 'package:geolocator/geolocator.dart';

class AdvancedLocationService {
  static StreamSubscription<Position>? _positionSubscription;

  /// 플랫폼별 최적화된 위치 스트림 시작
  static Stream<Position> getOptimizedPositionStream() {
    late LocationSettings locationSettings;

    if (Platform.isAndroid) {
      // Android 전용 설정
      locationSettings = AndroidSettings(
        accuracy: LocationAccuracy.high,
        distanceFilter: 10,
        // 포그라운드 서비스 알림 설정
        foregroundNotificationConfig: const ForegroundNotificationConfig(
          notificationText: '위치를 추적하고 있습니다',
          notificationTitle: '위치 추적 중',
          enableWakeLock: true,
        ),
      );
    } else if (Platform.isIOS) {
      // iOS 전용 설정
      locationSettings = AppleSettings(
        accuracy: LocationAccuracy.high,
        activityType: ActivityType.fitness,  // 운동 앱
        distanceFilter: 10,
        pauseLocationUpdatesAutomatically: true,  // 정지 시 자동 일시정지
        showBackgroundLocationIndicator: true,  // 상태바 위치 아이콘
      );
    } else {
      // 기타 플랫폼 (Web 등)
      locationSettings = const LocationSettings(
        accuracy: LocationAccuracy.high,
        distanceFilter: 10,
      );
    }

    return Geolocator.getPositionStream(locationSettings: locationSettings);
  }

  /// 위치 서비스 상태 스트림
  static Stream<ServiceStatus> getServiceStatusStream() {
    return Geolocator.getServiceStatusStream();
  }

  /// 설정 화면 열기
  static Future<void> openSettings() async {
    await Geolocator.openAppSettings();
  }

  /// 위치 설정 화면 열기
  static Future<void> openLocationSettings() async {
    await Geolocator.openLocationSettings();
  }
}

class AdvancedLocationPage extends StatefulWidget {
  const AdvancedLocationPage({super.key});

  @override
  State<AdvancedLocationPage> createState() => _AdvancedLocationPageState();
}

class _AdvancedLocationPageState extends State<AdvancedLocationPage> {
  bool _isServiceEnabled = false;
  LocationPermission _permission = LocationPermission.denied;
  Position? _currentPosition;
  StreamSubscription<Position>? _positionSubscription;
  StreamSubscription<ServiceStatus>? _serviceSubscription;

  @override
  void initState() {
    super.initState();
    _checkStatus();
    _listenToServiceStatus();
  }

  @override
  void dispose() {
    _positionSubscription?.cancel();
    _serviceSubscription?.cancel();
    super.dispose();
  }

  Future<void> _checkStatus() async {
    final serviceEnabled = await Geolocator.isLocationServiceEnabled();
    final permission = await Geolocator.checkPermission();

    setState(() {
      _isServiceEnabled = serviceEnabled;
      _permission = permission;
    });
  }

  void _listenToServiceStatus() {
    _serviceSubscription = AdvancedLocationService.getServiceStatusStream().listen(
      (ServiceStatus status) {
        setState(() {
          _isServiceEnabled = status == ServiceStatus.enabled;
        });
      },
    );
  }

  Future<void> _startTracking() async {
    // 권한 확인 및 요청
    if (_permission == LocationPermission.denied) {
      _permission = await Geolocator.requestPermission();
      setState(() {});
    }

    if (_permission == LocationPermission.deniedForever) {
      // 설정으로 이동 안내
      showDialog(
        context: context,
        builder: (context) => AlertDialog(
          title: const Text('권한 필요'),
          content: const Text('위치 권한이 영구적으로 거부되었습니다. 설정에서 권한을 허용해주세요.'),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context),
              child: const Text('취소'),
            ),
            TextButton(
              onPressed: () {
                Navigator.pop(context);
                AdvancedLocationService.openSettings();
              },
              child: const Text('설정 열기'),
            ),
          ],
        ),
      );
      return;
    }

    if (_permission == LocationPermission.whileInUse ||
        _permission == LocationPermission.always) {
      _positionSubscription = AdvancedLocationService.getOptimizedPositionStream()
          .listen((Position position) {
        setState(() {
          _currentPosition = position;
        });
      });
    }
  }

  void _stopTracking() {
    _positionSubscription?.cancel();
    _positionSubscription = null;
    setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('고급 위치 설정')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            // 상태 카드
            Card(
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  children: [
                    _StatusRow(
                      label: '위치 서비스',
                      value: _isServiceEnabled ? '활성화' : '비활성화',
                      isOk: _isServiceEnabled,
                    ),
                    const SizedBox(height: 8),
                    _StatusRow(
                      label: '권한 상태',
                      value: _permission.name,
                      isOk: _permission == LocationPermission.whileInUse ||
                          _permission == LocationPermission.always,
                    ),
                  ],
                ),
              ),
            ),

            const SizedBox(height: 16),

            // 위치 정보
            if (_currentPosition != null)
              Card(
                child: Padding(
                  padding: const EdgeInsets.all(16),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const Text('현재 위치', style: TextStyle(fontWeight: FontWeight.bold)),
                      const SizedBox(height: 8),
                      Text('위도: ${_currentPosition!.latitude.toStringAsFixed(6)}'),
                      Text('경도: ${_currentPosition!.longitude.toStringAsFixed(6)}'),
                    ],
                  ),
                ),
              ),

            const Spacer(),

            // 버튼들
            ElevatedButton(
              onPressed: _positionSubscription == null ? _startTracking : _stopTracking,
              child: Text(_positionSubscription == null ? '추적 시작' : '추적 중지'),
            ),
            const SizedBox(height: 8),
            OutlinedButton(
              onPressed: () => AdvancedLocationService.openLocationSettings(),
              child: const Text('위치 설정 열기'),
            ),
          ],
        ),
      ),
    );
  }
}

class _StatusRow extends StatelessWidget {
  final String label;
  final String value;
  final bool isOk;

  const _StatusRow({
    required this.label,
    required this.value,
    required this.isOk,
  });

  @override
  Widget build(BuildContext context) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.spaceBetween,
      children: [
        Text(label),
        Row(
          children: [
            Icon(
              isOk ? Icons.check_circle : Icons.error,
              color: isOk ? Colors.green : Colors.red,
              size: 20,
            ),
            const SizedBox(width: 4),
            Text(value),
          ],
        ),
      ],
    );
  }
}
